bash: {"command": "python3 - << 'PY'
import json, os, subprocess, datetime

def run(cmd):
    try:
        return subprocess.check_output(cmd, shell=True, text=True).strip()
    except Exception as e:
        return f"ERR: {e}"

data = {}

# OS / kernel
data['os'] = run('grep -m1 ^PRETTY_NAME= /etc/os-release 2>/dev/null || grep -m1 ^NAME= /etc/os-release 2>/dev/null || echo "OS: unknown"')
data['kernel'] = run('uname -r')
data['arch'] = run('uname -m')
data['hostname'] = run('hostname')
data['uptime'] = run('uptime -p 2>/dev/null || uptime')

# Users
users = []
try:
    with open('/etc/passwd') as f:
        for line in f:
            if not line.strip(): continue
            parts = line.strip().split(':')
            if len(parts) >= 3:
                users.append({'user': parts[0], 'uid': int(parts[2]), 'gid': int(parts[3]), 'shell': parts[6]})
except Exception:
    pass
data['users'] = users
data['current_user'] = run('whoami')
data['current_uid'] = run('id -u')
data['current_groups'] = run('id -Gn')

# SUID/SGID
suid = []
try:
    out = subprocess.check_output("find / -path /proc -prune -o -type f -perm -4000 -ls 2>/dev/null | head -n 50", shell=True, text=True)
    for line in out.strip().splitlines():
        if line:
            suid.append(line)
except Exception:
    pass
sgid = []
try:
    out = subprocess.check_output("find / -path /proc -prune -o -type f -perm -2000 -ls 2>/dev/null | head -n 50", shell=True, text=True)
    for line in out.strip().splitlines():
        if line:
            sgid.append(line)
except Exception:
    pass
data['suid_count'] = len(suid)
data['suid_sample'] = suid
data['sgid_count'] = len(sgid)
data['sgid_sample'] = sgid

# Top processes by memory
data['top_mem_procs'] = []
try:
    out = run("ps -eo pid,ppid,user,stat,pcpu,pmem,cmd --sort=-pmem | head -n 15")
    lines = [l for l in out.splitlines() if l.strip()]
    if lines:
        header = lines[0]
        for l in lines[1:]:
            parts = l.split(None, 6)
            if len(parts) >= 7:
                data['top_mem_procs'].append({
                    'pid': parts[0],
                    'ppid': parts[1],
                    'user': parts[2],
                    'stat': parts[3],
                    'pcpu': parts[4],
                    'pmem': parts[5],
                    'cmd': parts[6]
                })
except Exception:
    pass

# systemd services
data['services_active'] = 0
data['services_failed'] = 0
try:
    out = run("systemctl list-units --type=service --state=running --no-legend 2>/dev/null | wc -l")
    data['services_active'] = int(out) if out.isdigit() else 0
    out = run("systemctl list-units --type=service --state=failed --no-legend 2>/dev/null | wc -l")
    data['services_failed'] = int(out) if out.isdigit() else 0
except Exception:
    pass

# Network
data['net_connections'] = []
try:
    out = run("ss -tunap 2>/dev/null | head -n 100")
    for line in out.splitlines():
        if line.strip():
            data['net_connections'].append(line)
except Exception:
    pass
data['listening_ports'] = []
try:
    out = run("ss -tulnp 2>/dev/null | tail -n +2 | awk '{print $5}' | grep -Eo ':[0-9]+' | sed 's/^://' | sort -n | uniq")
    data['listening_ports'] = [int(p) for p in out.splitlines() if p.isdigit()]
except Exception:
    pass

# Disks / mounts
data['df_h'] = []
try:
    out = run("df -hP 2>/dev/null | tail -n +2")
    for line in out.splitlines():
        if line.strip():
            parts = line.split()
            if len(parts) >= 6:
                data['df_h'].append({
                    'fs': parts[0],
                    'size': parts[1],
                    'used': parts[2],
                    'avail': parts[3],
                    'use%': parts[4],
                    'mount': parts[5]
                })
except Exception:
    pass
data['mounts'] = []
try:
    with open('/proc/mounts') as f:
        for line in f:
            if line.strip():
                parts = line.split()
                if len(parts) >= 3:
                    data['mounts'].append({'fs': parts[0], 'mount': parts[1], 'type': parts[2], 'opts': parts[3]})
except Exception:
    pass
data['lsblk'] = []
try:
    out = run("lsblk -b -P -o NAME,SIZE,TYPE,MOUNTPOINT 2>/dev/null")
    for line in out.splitlines():
        kv = {}
        for part in line.split():
            if '=' in part:
                k, v = part.split('=', 1)
                kv[k] = v.strip('"')
        if kv:
            data['lsblk'].append(kv)
except Exception:
    pass

# CPU / memory
try:
    with open('/proc/loadavg') as f:
        data['loadavg'] = f.read().strip()
except Exception:
    data['loadavg'] = ''
meminfo = {}
try:
    with open('/proc/meminfo') as f:
        for line in f:
            if ':' in line:
                k, v = line.split(':', 1)
                meminfo[k.strip()] = v.strip()
except Exception:
    pass
data['meminfo'] = meminfo

# Cron / timers
data['user_crontab'] = ''
try:
    data['user_crontab'] = run('crontab -l 2>/dev/null || echo ""')
except Exception:
    pass
data['cron_d'] = []
try:
    if os.path.isdir('/etc/cron.d'):
        for f in os.listdir('/etc/cron.d'):
            data['cron_d'].append(f)
except Exception:
    pass
data['systemd_timers'] = []
try:
    out = run("systemctl list-timers --all --no-legend 2>/dev/null | head -n 50")
    for line in out.splitlines():
        if line.strip():
            data['systemd_timers'].append(line)
except Exception:
    pass

# Write JSON
with open('/workspace/project/system_audit_report.json', 'w', encoding='utf-8') as jf:
    json.dump(data, jf, ensure_ascii=False, indent=2)

# Write summary
lines = []
lines.append(f"Отчёт: {datetime.datetime.now().isoformat()}")
lines.append(f"ОС: {data.get('os','')}")
lines.append(f"Ядро: {data.get('kernel','')}")
lines.append(f"Текущий пользователь: {data.get('current_user','')} (UID={data.get('current_uid','')})")
high_uid = [u['user'] for u in data.get('users',[]) if u.get('uid',0)>=1000]
lines.append(f"Пользователи с UID>=1000: {', '.join(high_uid) if high_uid else '—'}")
lines.append(f"SUID: {data.get('suid_count',0)}; SGID: {data.get('sgid_count',0)}")
top_mem = data.get('top_mem_procs', [])
if top_mem:
    lines.append(f"Топ по памяти: PID {top_mem[0].get('pid')} ({top_mem[0].get('pmem')}% MEM) — {top_mem[0].get('cmd','')}")
else:
    lines.append("Топ по памяти: —")
lines.append(f"systemd: активных служб {data.get('services_active',0)}, сбойных {data.get('services_failed',0)}")
ports = data.get('listening_ports', [])
lines.append(f"Слушающих портов: {len(ports)} — {' '.join(map(str, sorted(ports)))}")
lines.append(f"Точек монтирования (df -h): {len(data.get('df_h',[]))}")
lines.append(f"Load average: {data.get('loadavg','')}")
mi = data.get('meminfo',{})
mem_total = mi.get('MemTotal','').split()[0] if 'MemTotal' in mi else ''
mem_avail = mi.get('MemAvailable','').split()[0] if 'MemAvailable' in mi else ''
lines.append(f"Память: Total≈{mem_total} kB, Available≈{mem_avail} kB")
lines.append(f"User crontab: {'есть' if data.get('user_crontab','').strip() else 'нет'}")
lines.append(f"/etc/cron.d: {len(data.get('cron_d',[]))} файлов")
lines.append(f"systemd timers: {len(data.get('systemd_timers',[]))}")
with open('/workspace/project/system_audit_summary.txt', 'w', encoding='utf-8') as sf:
    sf.write('\n'.join(lines))

print('WROTE')
